async function scanBundle(input, deliver) {
  let lineNumber = 1;
  let delivered = 0;
  let decoder;
  let parts;
  let hasUnterminatedLine;

  const resetLine = () => {
    decoder = new TextDecoder("utf-8");
    parts = [];
    hasUnterminatedLine = false;
  };

  const appendBytes = (bytes) => {
    if (bytes.length === 0) return;

    const text = decoder.decode(bytes, { stream: true });
    if (text !== "") parts.push(text);
    hasUnterminatedLine = true;
  };

  const finishLine = async () => {
    const tail = decoder.decode();
    if (tail !== "") parts.push(tail);

    let text = parts.length === 0 ? "" : parts.join("");
    if (text.endsWith("\r")) text = text.slice(0, -1);

    if (text.trim() === "") return false;

    let value;
    try {
      value = JSON.parse(text);
    } catch {
      const error = new Error("Invalid JSON line");
      error.code = "BAD_LINE";
      error.line = lineNumber;
      throw error;
    }

    delivered += 1;
    const result = await deliver(value, lineNumber);
    return result === false;
  };

  try {
    resetLine();

    for (;;) {
      const chunk = await input.read();
      if (chunk === null) break;

      let start = 0;

      for (let index = 0; index < chunk.length; index += 1) {
        if (chunk[index] !== 0x0a) continue;

        appendBytes(chunk.subarray(start, index));

        if (await finishLine()) return delivered;

        lineNumber += 1;
        resetLine();
        start = index + 1;
      }

      if (start < chunk.length) {
        appendBytes(chunk.subarray(start));
      }
    }

    if (hasUnterminatedLine && await finishLine()) {
      return delivered;
    }

    return delivered;
  } finally {
    await input.close();
  }
}
